1: /* ===========================================================================
2:    Mission Control — base layer (shell geometry, type, focus, motion)
3: 
4:    Ends the ~15-way `.shell` grid conflict with ONE authoritative rule and
5:    normalises the shared reading grammar. Scoped tight enough to win over the
6:    historical `!important` rules without introducing new ones where avoidable.
7:    ======================================================================== */
8: 
9: /* ------------------------------------------------------------ shell layout
10: 
11:    The sidebar is a deliberate icon rail (labels live in tooltips + the command
12:    palette, per the Experience Audit). Match its width exactly so there is no
13:    dead column beside it. */
14: 
15: /* ------------------------------------------------------------ shell layout
16: 
17:    The sidebar is a deliberate icon rail (labels live in tooltips + the command
18:    palette, per the Experience Audit). Match its width exactly so there is no
19:    dead column beside it. */
20: 
21: html body {
22:   background-color: var(--mc-void) !important;
23:   background-image:
24:     radial-gradient(at 12% 14%, rgba(79, 157, 255, 0.08) 0px, transparent 48%),
25:     radial-gradient(at 88% 18%, rgba(143, 123, 255, 0.07) 0px, transparent 52%),
26:     radial-gradient(at 50% 86%, rgba(62, 207, 142, 0.04) 0px, transparent 60%) !important;
27:   background-attachment: fixed !important;
28: }
29: 
30: html body #root .shell {
31:   display: grid !important;
32:   grid-template-columns: 64px minmax(0, 1fr) !important;
33:   grid-template-rows: minmax(0, 1fr) !important;
34:   width: 100%;
35:   height: 100%;
36:   overflow: hidden !important;
37:   background: transparent !important;
38:   color: var(--mc-text);
39:   font-family: var(--font-family-ui, "Inter", "Segoe UI", system-ui, sans-serif);
40: }
41: @media (max-width: 720px) {
42:   html body #root .shell { grid-template-columns: 52px minmax(0, 1fr) !important; }
43: }
44: 
45: .shell .main-area { min-width: 0; min-height: 0; overflow: hidden; background: transparent; }
46: .shell .experience {
47:   min-width: 0;
48:   min-height: 0;
49:   padding: var(--mc-space-6) var(--mc-space-8) var(--mc-space-8);
50:   overflow-x: hidden;
51:   overflow-y: auto;
52:   background: transparent;
53: }
54: /* Match the loaded premiumV3 selector so its scrollable Workspace rule cannot
55:    win on specificity and retain a stale scroll/anchor position. */
56: html body #root .shell > .main-area > .experience.view-workspace {
57:   height: auto;
58:   align-self: stretch;
59:   padding: 10px !important;
60:   overflow: hidden !important;
61:   background: transparent !important;
62: }
63: 
64: /* Nothing inside a screen may push the page wider than its column. */
65: .shell .experience > * { max-width: 100%; }
66: .shell :is(.mc-ref-groundstation, .needs-view, .history-view, .agents-view,
67:            .integrations-page, .recipes-page, .settings-hub, .projects-view) {
68:   min-width: 0;
69:   max-width: 1360px;
70:   margin-inline: auto;
71: }
72: .shell :is(.mc-ref-manifest-row, .mc-ref-readout, .need-item, .integration-row,
73:            .recipe-row) { min-width: 0; max-width: 100%; }
